def convert(text):
    try:
        return int(text)
    except ValueError as e:
        print("值错误：", e)
    except TypeError as e:
        print("类型错误：", e)
    return None

print(convert("12"))     # 12
print(convert("abc"))    # 值错误：invalid literal for int() ...
print(convert(None))     # 类型错误：int() argument must be ...

def set_age(age):
    if not isinstance(age, int):
        raise TypeError("年龄必须是整数")
    if age < 0 or age > 150:
        raise ValueError("年龄超出合理范围")
    return age

try:
    set_age(-5)
except ValueError as e:
    print(e)

